class PlanManager(EMSSInterface):
    """
    EMSsim keywords related to plan (creating/deleting objects) management
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(PlanManager, self).__init__()

    def set(self, key_name, value, enb_id=None, bts_id=None, alias=None):
        """
        Sets internal key_name to the given value. The key_name is evaluated in configure function. \
        If a yaml config file contains the evaluate expression like ${key_name} then the 'key_name' \
        is replaced by the given value before execution of any plan related commands.

        :param key_name: (string) name of the key to store
        :param value: (string) value of the key to store
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------+------------------+--------+
        |             Examples              |
        +=======+==================+========+
        |  set  |  RTT_BAND_CLASS  |  bc0   |
        +-------+------------------+--------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_om(), "OM does not exist")
        self._get_om().set(key_name, value)

    def get(self, key_name, enb_id=None, bts_id=None, alias=None):
        """
        Gets internal key_name value set earlier by set() function

        :param key_name: (string) name of the key to retrieve
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------+-------------------+
        |          Examples          |
        +========+===================+
        |   get  |  RTT_BAND_CLASS   |
        +--------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_om(), "OM does not exist")
        return self._get_om().get(key_name)

    def configure_bts(self, config, skip_np=True, delta_yaml=False, timeout=3600, enb_id=None, bts_id=None, alias=None):
        """
        Configures enb using yaml file or given configuration plan structure in the format:
        'MOC': <MOC>, 'ID': <ID>, attr1: val1, attr2: val2, ... attrN: valN, where ID is hyphen
        separated list of parent IDs until LNBTS or MRBTS object exclusively, e.g. MOC/ID of the distName
        "MRBTS-1/TNLSVC-1/TNL-1/IPNO-1" is: 'MOC': 'IPNO', 'ID': '1-1-1', and the distName "MRBTS-1/LNBTS-1/LNCEL-1/DRX-0
        is: 'MOC': 'DRX', 'ID': '1-0'.

        :param config: (string or dict or list) path to yaml, xml or json file or configuration plan structure
        :param skip_np: (bool, default=True) skip not present attributes, i.e. marked in NIDD as Hidden or Not Used
        :param delta_yaml: (bool, default=False) generate delta yaml file, useful to convert xml or json to yaml file on the fly
        :param timeout: Time to wait for configure flow to complete (default=3600 s)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+----------------------------------------------------------------------------------------+
        |            Examples                                                                                           |
        +======================+========================================================================================+
        | configure_bts        | /path/to/config.yaml                                                                   |
        +----------------------+----------------------------------------------------------------------------------------+
        | configure_bts        | {'MOC': 'LNCEL', 'ID': '1', 'pcellSwapConfig': [{'numCaUeThreshold': '0'}]}            |
        +----------------------+----------------------------------------------------------------------------------------+
        """
        skip_np = self._opt_bool(skip_np)
        delta_yaml = self._opt_bool(delta_yaml)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_om(), "OM does not exist")

        if isinstance(config, list):
            config = self._struct_to_yaml_file(config)
        elif isinstance(config, dict):
            config = self._struct_to_yaml_file([config])

        opts = [config]
        if skip_np:
            opts.append("-skip_errors")
        if delta_yaml:
            opts.append("-yaml")

        return self.run_emssim_command("configure", opts, get_full_data=True, timeout=timeout)

    def configure(self, config, name=None, skip_ro=True, skip_np=True, skip_dc=False, use_admin=False, activate=False,
                  enb_id=None, bts_id=None, alias=None):
        """
        Configures enb using yaml file or given configuration plan structure in the format:
        'MOC': <MOC>, 'ID': <ID>, attr1: val1, attr2: val2, ... attrN: valN, where ID is hyphen
        separated list of parent IDs until LNBTS or MRBTS object exclusively, e.g. MOC/ID of the distName
        "MRBTS-1/TNLSVC-1/TNL-1/IPNO-1" is: 'MOC': 'IPNO', 'ID': '1-1-1', and the distName "MRBTS-1/LNBTS-1/LNCEL-1/DRX-0
        is: 'MOC': 'DRX', 'ID': '1-0'.
        Passing xml first converts it to yaml file

        :param config: (string or dict or list) path to yaml, xml or json file or configuration plan structure
        :param name: (string) symbolic name for the configuration plan (can be used later in deconfigure)
        :param skip_ro: (bool, default=True) skip Read-Only attributes (do not rise an error on RO attribute modification)
        :param skip_np: (bool, default=True) skip not present attributes, i.e. marked in NIDD as Hidden or Not Used
        :param skip_dc: (bool, default=False) do not store this config plan for further deconfiguration
        :param activate: (bool, default=False) activate the plan together with download, check in NIDD if allowed for a given MOC
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param use_admin: Execute delta commissioning using ute_admin. It also forces skip_dc=True

        +----------------------+------------------------------+---------------------------------------------------------+
        |            Examples                                                                                           |
        +======================+==============================+=========================================================+
        | configure            | /path/to/config.yaml                                                                   |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | /path/to/config.yaml         |    FRXYZ_A_a_1                                          |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | /path/to/config.xml                                                                    |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | /path/to/config.json                                                                   |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | {'MOC': 'LNCEL', 'ID': '1', 'inactivityTimer': '10'}                                   |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | [{'MOC': 'LNCEL', 'ID': '1', 'inactivityTimer': '10'},                                 |
        |                      |  {'MOC': 'LNCEL', 'ID': '2', 'inactivityTimer': '10'},                                 |
        |                      |  {'MOC': 'LNCEL', 'ID': '3', 'inactivityTimer': '10'}]                                 |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | {'MOC': 'LNCEL', 'ID': '1', 'pcellSwapConfig': [{'numCaUeThreshold': '0'}]}            |
        +----------------------+------------------------------+---------------------------------------------------------+
        | configure            | {'MOC': 'DRX', 'ID': '1-0'',                                                           |
        |                      |  'drxProfile1': [{'drxProfilePriority': '45'}],                                        |
        |                      |  'drxProfile2': [{'drxOnDuratT': '10', 'drxRetransT': '16',                            |
        |                      |  'drxInactivityT': '4', 'drxProfilePriority': '40', 'drxLongCycle': '40ms'}],          |
        |                      |  'drxProfile3': [{'drxOnDuratT': '10', 'drxRetransT': '16',                            |
        |                      |  'drxInactivityT': '10', 'drxProfilePriority': '30', 'drxLongCycle': '80ms'}],         |
        |                      |  'drxProfile4': [{'drxOnDuratT': '20', 'drxRetransT': '16',                            |
        |                      |  'drxInactivityT': '500', 'drxProfilePriority': '20', 'drxLongCycle': '320ms'}],       |
        |                      |  'drxProfile5': [{'drxOnDuratT': '20', 'drxRetransT': '16',                            |
        |                      |  'drxInactivityT': '2560', 'drxProfilePriority': '10', 'drxLongCycle': '2560ms'}],     |
        |                      |  'stInactFactor': '1', 'applyOutOfSyncState': 'extendedDrxOnly',                       |
        |                      |  'drxApplyDeviceType': 'true'}                                                         |
        +----------------------+------------------------------+---------------------------------------------------------+
        """
        skip_ro = self._opt_bool(skip_ro)
        skip_np = self._opt_bool(skip_np)
        skip_dc = self._opt_bool(skip_dc)
        bts_id = self._opt_id(enb_id, bts_id)
        use_admin = self._opt_bool(use_admin) or self.use_admin

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        self._assert(self._get_om(), "OM does not exist")

        if use_admin:
            self._get_om().configure(config, name=name, skip_ro=skip_ro, skip_np=skip_np, skip_dc=True, send=False)
            plan_generate_command = self._get_emssim().cmd_plan_generate()
            plan_generate_command.run()
            if not self._delta_via_admin(plan_generate_command):
                self.destroy_existing_plan()
        else:
            self._get_om().configure(config, name=name, skip_ro=skip_ro, skip_np=skip_np, skip_dc=skip_dc, activate=activate)

    def configure_and_wait(self, config, name=None, skip_ro=True, skip_np=True, wait=60, wait_on_air=True, activate=False,
                           enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Configures enb using yaml file or given configuration plan structure (see 'configure' for plan syntax).
        If configuration file had attribute which needed BTS restart, waits defined number of seconds.
        Passing xml first converts it to yaml file

        :param config: (string or dict or list) path to yaml, xml or json file or configuration plan structure
        :param name: (string) symbolic name for the configuration plan (can be used later in deconfigure)
        :param skip_ro: (bool, default=True) skip Read-Only attributes (do not rise an error on RO attribute modification)
        :param skip_np: (bool, default=True) skip not present attributes, i.e. marked in NIDD as Hidden or Not Used
        :param wait: (integer, default=60) wait given number of seconds for BTS restart before first BTS state verification
        :param wait_on_air: (bool, default=True) wait for enb on air
        :param activate: (bool, default=False) activate the plan together with download, check in NIDD if allowed for a given MOC
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param kwargs: keyword arguments passed to wait_for_enb_on_air method

        +----------------------+------------------------------+---------------+---------------+------------+
        |            Examples                                                                              |
        +======================+==============================+===============+===============+============+
        | configure_and_wait   | /path/to/config.yaml                                                      |
        +----------------------+------------------------------+---------------+---------------+------------+
        | configure_and_wait   | /path/to/config.yaml         |    FRXYZ_A_a_1                             |
        +----------------------+------------------------------+---------------+---------------+------------+
        | configure_and_wait   | /path/to/config.xml          | skip_ro=False | skip_np=False |  wait=145  |
        +----------------------+------------------------------+---------------+---------------+------------+
        | configure_and_wait   | /path/to/config.xml          |         wait_on_air=False                  |
        +----------------------+------------------------------+---------------+---------------+------------+
        | configure_and_wait   | /path/to/config.json                                                      |
        +----------------------+------------------------------+---------------+---------------+------------+
        | configure_and_wait   | {'MOC': 'LNCEL', 'ID': '1', 'inactivityTimer': '10'}                      |
        +----------------------+------------------------------+---------------+---------------+------------+
        | configure_and_wait   | [{'MOC': 'LNCEL', 'ID': '1', 'inactivityTimer': '10'},                    |
        |                      |  {'MOC': 'LNCEL', 'ID': '2', 'inactivityTimer': '10'},                    |
        |                      |  {'MOC': 'LNCEL', 'ID': '3', 'inactivityTimer': '10'}]                    |
        +----------------------+------------------------------+---------------+---------------+------------+
        """
        skip_ro = self._opt_bool(skip_ro)
        skip_np = self._opt_bool(skip_np)
        wait = self._opt_int(wait)
        wait_on_air = self._opt_bool(wait_on_air)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias=alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        self._assert(self._get_om(), "OM does not exist")
        self._get_om().configure(config, name=name, skip_ro=skip_ro, skip_np=skip_np, activate=activate)
        conf = self._get_om().get_last_configurator(name)
        if conf.is_reset_required() or activate:
            sleep(wait)
            if wait_on_air:
                timeout = 300
                self.wait_for_enb_on_air(timeout, bts_id=bts_id, alias=alias, **kwargs)

    def configure_delete(self, moc, strict=False, enb_id=None, bts_id=None, alias=None):
        """
        Deletes objects with given moc and their children. With specific ID, deletes only object with that ID and all of its children.
        :param moc: Managed object class or instance to be deleted
        :param strict: (bool, default=False) if True than throw an error if MOC does not exist
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+------------+
        |              Examples             |
        +======================+============+
        |   configure_delete   |   LNCEL    |
        +----------------------+------------+
        |   configure_delete   |  LNCEL-2   |
        +----------------------+------------+
        """
        strict = self._opt_bool(strict)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias=alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        self._assert(self._get_om(), "OM does not exist")
        objs = self._get_om().get_parent_tree(moc)
        if strict:
            self._assert(objs, "Delete object tree {} operation failed. Empty list.".format(moc))
        if objs:
            self.create_new_plan(bts_id=bts_id, alias=alias)
            for obj in reversed(objs):
                self.plan_object_deletion(obj, bts_id=bts_id, alias=alias)
            self.apply_planned_changes(bts_id=bts_id, alias=alias)

    def deconfigure(self, name=None, enb_id=None, bts_id=None, alias=None):
        """
        Deconfigures previous configuration (the last execution of unnamed configure or referenced via name)

        :param name: (string) name of the configuration to deconfigure (used earlier in configure).
                     If empty then last auto-generated (unnamed) config ID is taken.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+------------------+
        |            Examples                     |
        +======================+==================+
        | deconfigure          | FRXYZ_A_a_1      |
        +----------------------+------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        self._assert(self._get_om(), "OM does not exist")
        self._get_om().deconfigure(name)

    def deconfigure_last(self, enb_id=None, bts_id=None, alias=None):
        """
        Deconfigures last unnamed configuration (the last execution of configure without name option)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+------------------+
        |            Examples                     |
        +======================+==================+
        | deconfigure_last     |                  |
        +----------------------+------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        self._assert(self._get_om(), "OM does not exist")
        self._get_om().deconfigure_last()

    def deconfigure_all(self, enb_id=None, bts_id=None, alias=None):
        """
        Deconfigures all previous unnamed configurations (all of the previous configure executions without name option)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+------------------+
        |            Examples                     |
        +======================+==================+
        | deconfigure_all      |                  |
        +----------------------+------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        self._assert(self._get_om(), "OM does not exist")
        self._get_om().deconfigure_all()

    def create_new_plan(self, abandon_old=True, enb_id=None, bts_id=None, alias=None):
        """
        Creates new plan needed for adding/deleting objects.

        :param abandon_old: (bool, default=True) if set, keyword will destroy currently stored plan
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+
        |     Examples    |
        +=================+
        | create_new_plan |
        +-----------------+
        """
        abandon_old = self._opt_bool(abandon_old)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        if abandon_old:
            dstr = self._get_emssim().cmd_plan_destroy()
            dstr.run()
        plan_create_command = self._get_emssim().cmd_plan_create()
        command_succeeded = plan_create_command.run()
        self._assert(command_succeeded, "Creating New Plan operation failed: %s" % plan_create_command.failure_reason)

    def destroy_existing_plan(self, enb_id=None, bts_id=None, alias=None):
        """
        Deletes current plan and it's content.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------------+
        |        Examples       |
        +=======================+
        | destroy_existing_plan |
        +-----------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._get_emssim().cmd_plan_show().run()
        self._get_emssim().cmd_plan_destroy().run()

    def plan_object_creation(self, object_to_create, only_mandatory=False, enb_id=None, bts_id=None, alias=None):
        """
        Adds object creation procedure to the plan.

        :param object_to_create: (string) Name of a new object to create.
        :param only_mandatory: (bool, default=False) add only mandatory attributes
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+---------+
        |            Examples            |
        +======================+=========+
        | plan_object_creation | LNCEL-8 |
        +----------------------+---------+
        """
        only_mandatory = self._opt_bool(only_mandatory)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        params = object_to_create
        if only_mandatory:
            params = params + " -mandatory"
        plan_add_command = self._get_emssim().cmd_plan_add()
        command_succeeded = plan_add_command.run(params)
        self._assert(command_succeeded, "Adding %s object creation to the plan failed: %s" %
                     (object_to_create, plan_add_command.failure_reason))

    def plan_object_creation_if_not_exists(self, object_to_create, enb_id=None, bts_id=None, alias=None):
        """
        If object does not exist, the method will add object creation procedure to the plan.

        :param object_to_create: (string) Name of an object to create.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------------------------------+---------+
        |                   Examples                   |
        +====================================+=========+
        | plan_object_creation_if_not_exists | LNCEL-8 |
        +------------------------------------+---------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if not self.check_if_object_exists(object_to_create):
            self.plan_object_creation(object_to_create, bts_id=bts_id, alias=alias)

    def plan_attribute_creation(self, existing_object, attribute_to_create, only_mandatory=False, enb_id=None, bts_id=None, alias=None):
        """
        Adds existing object's attribute creation procedure to the plan.

        :param existing_object: (string) Name of a existing object.
        :param attribute_to_create: (string) Name of a new attribute to create.
        :param only_mandatory: (bool, default=False) add only mandatory attributes
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------+---------+-----------------+
        |                     Examples                         |
        +==========================+=========+=================+
        | plan_attribute_creation  | LNCEL-8 | moprmappinglist |
        +--------------------------+---------+-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        params = " ".join([existing_object, attribute_to_create])
        if only_mandatory:
            params = params + " -mandatory"
        plan_add_command = self._get_emssim().cmd_plan_add()
        command_succeeded = plan_add_command.run(params)
        self._assert(command_succeeded, "Adding %s attribute of %s object creation to the plan failed: %s" %
                     (attribute_to_create, existing_object, plan_add_command.failure_reason))

    def plan_attribute_creation_if_not_exists(self, existing_object, attribute_to_create, enb_id=None, bts_id=None, alias=None):
        """
        If attribute does not exist, the method will add attribute creation procedure to the plan.

        :param existing_object: (string) Name of a existing object.
        :param attribute_to_create: (string) Name of a new attribute to create.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------------------+---------+-----------------+
        |                              Examples                              |
        +========================================+=========+=================+
        | plan_attribute_creation_if_not_exists  | LNCEL-8 | moprmappinglist |
        +----------------------------------------+---------+-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if not self.check_if_attribute_exists(existing_object, attribute_to_create):
            self.plan_attribute_creation(existing_object, attribute_to_create)

    def plan_object_deletion(self, object_to_delete, enb_id=None, bts_id=None, alias=None):
        """
        Adds object deletion procedure to the plan.

        :param object_to_delete: (string)  Name of the existing object to delete.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------+---------+
        |            Examples            |
        +======================+=========+
        | plan_object_deletion | LNCEL-2 |
        +----------------------+---------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        plan_delete_command = self._get_emssim().cmd_plan_delete()
        command_succeeded = plan_delete_command.run(object_to_delete)
        self._assert(command_succeeded, "Adding %s object deletion to the plan failed: %s" %
                     (object_to_delete, plan_delete_command.failure_reason))

    def plan_object_deletion_if_exists(self, object_to_delete, enb_id=None, bts_id=None, alias=None):
        """
        If object exists, the method will add object deletion procedure to the plan.

        :param object_to_delete: (string)  Name of the object to delete.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------------+---------+
        |                 Examples                 |
        +================================+=========+
        | plan_object_deletion_if_exists | LNCEL-2 |
        +--------------------------------+---------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if self.check_if_object_exists(object_to_delete):
            self.plan_object_deletion(object_to_delete)

    def plan_attribute_deletion(self, object_name, attribute, enb_id=None, bts_id=None, alias=None):
        """
        Deletes given object's attribute.

        :param object_name: Object name
        :param attribute: Attribute name to delete
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------------------+---------+-----------------+
        |                       Examples                      |
        +=========================+=========+=================+
        | plan_attribute_deletion | LNCEL-4 | moprmappinglist |
        +-------------------------+---------+-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(attribute.strip(), "attribute value cannot be empty")
        plan_delete_command = self._get_emssim().cmd_plan_delete()
        command_succeeded = plan_delete_command.run(object_name, attribute)
        self._assert(command_succeeded, "Adding attribute %s of %s object deletion to the plan failed: %s" %
                     (attribute, object_name, plan_delete_command.failure_reason))

    def remove_object_from_plan(self, object_name, enb_id=None, bts_id=None, alias=None):
        """
        Removes object from the current plan.

        Note: this keyword does NOT delete existing object, use plan_object_deletion instead.

        :param object_name: (string)  Name of the object to remove from the plan.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------------------+---------+
        |              Examples             |
        +=========================+=========+
        | remove_object_from_plan | LNCEL-2 |
        +-------------------------+---------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        plan_remove_command = self._get_emssim().cmd_plan_remove()
        command_succeeded = plan_remove_command.run(object_name)
        self._assert(command_succeeded, "Removing %s object from the plan failed: %s" % (object_name, plan_remove_command.failure_reason))

    def remove_attribute_from_plan(self, object_name, attribute, enb_id=None, bts_id=None, alias=None):
        """
        Removes object's attribute from the current plan.

        Note: this keyword does NOT delete existing attribute, use delete_object_attribute instead.

        :param object_name: (string)  Name of object existing in the plan.
        :param attribute: (string)  Name of the attribute to remove from plan.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------------------+---------+-------------------------------------+
        |                                  Examples                                  |
        +============================+=========+=====================================+
        | remove_attribute_from_plan | mopr-10 | refFreqListNaccGeran.referenceARFCN |
        +----------------------------+---------+-------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        params = "%s %s" % (object_name, attribute)
        plan_remove_command = self._get_emssim().cmd_plan_remove()
        command_succeeded = plan_remove_command.run(params)
        self._assert(command_succeeded, "Removing attribute %s of %s object from the plan failed: %s" %
                     (attribute, object_name, plan_remove_command.failure_reason))

    def edit_planned_object_attributes(self, object_name, dictionary_of_attributes=None,
                                       enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Sets values of new object already existing in the plan.

        :param object_name: (string) Name of a new object to create.
        :param dictionary_of_attributes: (dict) Dictionary of attributes to set. Format: {'attr1':value1, 'attr2':value2, 'attr3.field':value3 ...}
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param kwargs: one or more keyword argument describing attributes. Syntax:  key=value
            (eg.   attr1=value1    attr2=value2    attr3.field=value3, attr4.field[1]=value4),
            If no index specified, 0 will be taken(eg. attr.field => attr.field[0])
            In case of name overlapping, values specified in kwargs are set.

        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        |                                                           Examples                                                                 |
        +================================+=======================+==============================================+============================+
        | edit_planned_object_attributes |       LNREL-1-100     |                             cellindoffneigh=2dB                           |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        | edit_planned_object_attributes |         LNCEL-9       |              dictionary_of_attributes=${dict_from_the_file}               |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        | dictionary_of_attributes_usage                                                                                                     |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        |        ${lncel-1_attr}=        | get_object_attributes |                    LNCEL-1                   |     only_mandatory=True    |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        | edit_planned_object_attributes |         LNCEL-6       |   dictionary_of_attributes=${lncel-1_attr}   |                            |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        |      ${lnrel-1-198_attr}=      | get_object_attributes |                   LNREL-1-198                | without_set_by_system=True |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        | edit_planned_object_attributes |       LNREL-1-200     | dictionary_of_attributes=${lnrel-1-198_attr} |         ecgiLcrId=3        |
        +--------------------------------+-----------------------+----------------------------------------------+----------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if dictionary_of_attributes:
            self.edit_planned_object_attributes(object_name, bts_id=bts_id, alias=alias,
                                                **dict(self._keys_lower(dictionary_of_attributes), **self._keys_lower(kwargs)))
            return

        params = self._parse_edit_params(object_name, kwargs)
        plan_edit_command = self._get_emssim().cmd_plan_edit()
        command_succeeded = plan_edit_command.run(params)
        self._assert(command_succeeded, "Command plan_edit failed: %s" % plan_edit_command.failure_reason)

    def apply_planned_changes(self, activate=False, retry_limit=3, retry_sleep=30, enb_id=None, bts_id=None, alias=None):
        """
        Sends and activates currently stored plan.
        Make sure all mandatory attributes are set, otherwise sending the plan will fail.

        :param activate: (bool, default=False) activate the plan together with download, check in NIDD if allowed for a given MOC
        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=30)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------------+
        |        Examples       |
        +=======================+
        | apply_planned_changes |
        +-----------------------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered()
        self._clear_cache()
        self._wa_for_pdl_validation()

        self._get_emssim().cmd_plan_show().run()
        plan_send_command = self._get_emssim().cmd_plan_send()
        opt_activate = "-activate" if activate else ""
        command_succeeded = self._run_repeat_command(plan_send_command, opt_activate, retry_limit=retry_limit, retry_sleep=retry_sleep)
        self._assert(command_succeeded, "Applying plan failed: %s" % plan_send_command.failure_reason)
        #  WA to allow BTS to cleanup its plan and not generate BTS not ready cause when bunch configure run
        sleep(3)

    def plan_generate(self, enb_id=None, bts_id=None, alias=None):
        """
        Generate xml and json for currently stored plan.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------+
        |     Examples       |
        +====================+
        | plan_generate      |
        +--------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        plan_generate_command = self._get_emssim().cmd_plan_generate()
        command_succeeded = plan_generate_command.run()
        self._assert(command_succeeded, "Generating plan failed: %s" % plan_generate_command.failure_reason)

    def plan_records_deletion_from_structural_attribute_with_values(self, object_name, attribute, dictionary_of_subattributes=None,
                                                                    enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Adds list elements deletion procedure to plan. Selection of list elements of structural attribute depends on subattribute values.

        :param object_name: (string)  Name of the existing object
        :param attribute: (string) Name of structural attribute
        :param dictionary_of_subattributes: (dict) optional, dictionary containing subattributes to check ({"subattr1":value1, "subattr2":value2})
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param kwargs: one or more keyword argument describing subattributes. Syntax:  key=value (subattr1=value1    subattr2=value2 )

        +-------------------------------------------------------------+----------+----------------+-------------------------+
        |                                                   Examples                                                        |
        +=============================================================+==========+================+=========================+
        | plan_records_deletion_from_structural_attribute_with_values | LNBTS-11 | qciTabOperator | qciSupp='ENABLE'        |
        +-------------------------------------------------------------+----------+----------------+-------------------------+
        | plan_records_deletion_from_structural_attribute_with_values | LNBTS-11 | qciTabOperator | { 'qciSupp':'ENABLE' }  |
        +-------------------------------------------------------------+----------+----------------+-------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if dictionary_of_subattributes:
            return self.plan_records_deletion_from_structural_attribute_with_values(object_name, attribute, bts_id=bts_id, alias=alias,
                                                                                    **dict(dictionary_of_subattributes, **kwargs))

        # removing have to be done in descending order
        for index in sorted(self.get_indexes_of_list_elements_of_structural_attribute(object_name, attribute, kwargs), reverse=True):
            self.plan_attribute_deletion(object_name, str(attribute) + "[%s]" % index, bts_id=bts_id, alias=alias)

    def plan_record_of_structural_attribute_creation_with_values(self, object_name, attribute, dictionary_of_subattributes=None,
                                                                 enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Adds list element creation procedure to plan. List element with specified subattribute=values pairs will be created under index: \
        current_max_index +1, If more then 1 records will be added in 1 plan, the latest will overide others.

        :param object_name: (string)  Name of the existing object
        :param attribute: (string) Name of structural attribute
        :param dictionary_of_subattributes: (dict) optional, dictionary containing subattributes to check ({"subattr1":value1, "subattr2":value2})
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param kwargs: one or more keyword argument describing subattributes. Syntax:  key=value (subattr1=value1    subattr2=value2 )

        +------------------------------------------------------------+----------+----------------+------------------------+
        |                                                  Examples                                                       |
        +============================================================+==========+================+========================+
        | plan_record_of_structural_attribute_creation_with_values   | LNBTS-11 | qciTabOperator | qciSupp='ENABLE'       |
        +------------------------------------------------------------+----------+----------------+------------------------+
        | plan_record_of_structural_attribute_creation_with_values   | LNBTS-11 | qciTabOperator | {'qciSupp':'ENABLE' }  |
        +------------------------------------------------------------+----------+----------------+------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if dictionary_of_subattributes:
            return self.plan_record_of_structural_attribute_creation_with_values(object_name, attribute,
                                                                                 **dict(dictionary_of_subattributes, **kwargs))
        self.plan_attribute_creation(object_name, attribute)
        if self.check_if_attribute_exists(object_name, attribute):
            index = len(self.get_values_of_structural_attribute(object_name, attribute))
        else:
            index = 0
        subattributes_dict_parsed_for_edit = EmssStructuralAttribute.get_subattributes_dict_parsed_for_edit(attribute, kwargs, index)
        self.edit_planned_object_attributes(object_name, subattributes_dict_parsed_for_edit, bts_id=bts_id, alias=alias)

    def convert_xml(self, xml_file, output_path=None, enb_id=None, bts_id=None, alias=None):
        """
        Converts xml file to YAML file using scfc parser

        :param xml_file: Path to xml to be converted
        :param output_path: optional, YAML output file, if None default is /tmp/YAMLS/<xml_file_name_with_ts>.yaml
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------+-----------------------------+------------------------------+
        |                                 Examples                                 |
        +=============+=============================+==============================+
        | convert_xml | /path/to/xml_to_convert.xml |                              |
        +-------------+-----------------------------+------------------------------+
        | convert_xml | /path/to/xml_to_convert.xml | /path/for/output_config.yaml |
        +-------------+-----------------------------+------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._assert(self._get_om(), "OM does not exist")
        return self._get_om().convert_xml(xml_file, output_path)

    def _struct_to_yaml_file(self, config):
        ts = int(time.time())
        file_path = f"/tmp/emss.config.{self.emss_name}.{ts}.yaml"
        with open(file_path, "w") as yaml_handler:
            yaml_handler.write(yaml.safe_dump(config, encoding='utf-8', allow_unicode=True, default_flow_style=False).decode('utf-8', 'replace'))
        return file_path
